'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/scheduled-transfers — recurring or future-dated payouts.
 */
class ScheduledTransfers {
  constructor(client) {
    this.client = client;
  }

  /**
   * List scheduled transfers.
   * @param {object} [params]
   */
  list(params) {
    return this.client.request('GET', withQuery('/v1/scheduled-transfers', params));
  }

  /**
   * Create a scheduled transfer.
   * @param {object} params
   * @param {string} params.operator_code
   * @param {string} params.recipient_phone
   * @param {string} [params.recipient_name]
   * @param {number} params.amount
   * @param {string} params.currency
   * @param {string} [params.note]
   * @param {string} [params.external_ref]
   * @param {string} [params.frequency]     e.g. "once" | "daily" | "weekly" | "monthly" (see API docs)
   * @param {string} params.scheduled_at    ISO date/time of the first run
   * @param {string} [params.ends_at]       ISO date
   * @param {number} [params.max_runs]
   * @param {object} [params.metadata]
   */
  create(params) {
    return this.client.request('POST', '/v1/scheduled-transfers', params);
  }

  /**
   * Retrieve a scheduled transfer by ID.
   * @param {string} id
   */
  retrieve(id) {
    return this.client.request('GET', `/v1/scheduled-transfers/${encodeURIComponent(id)}`);
  }

  /**
   * Update a scheduled transfer.
   * @param {string} id
   * @param {object} params  amount?, note?, next_run_at?, ends_at?, max_runs?, metadata?
   */
  update(id, params) {
    return this.client.request('PATCH', `/v1/scheduled-transfers/${encodeURIComponent(id)}`, params);
  }

  /** Pause a scheduled transfer. @param {string} id */
  pause(id) {
    return this.client.request('POST', `/v1/scheduled-transfers/${encodeURIComponent(id)}/pause`);
  }

  /** Resume a paused scheduled transfer. @param {string} id */
  resume(id) {
    return this.client.request('POST', `/v1/scheduled-transfers/${encodeURIComponent(id)}/resume`);
  }

  /** Delete/cancel a scheduled transfer. @param {string} id */
  delete(id) {
    return this.client.request('DELETE', `/v1/scheduled-transfers/${encodeURIComponent(id)}`);
  }

  /** Trigger an out-of-schedule run immediately. @param {string} id */
  runNow(id) {
    return this.client.request('POST', `/v1/scheduled-transfers/${encodeURIComponent(id)}/run-now`);
  }
}

module.exports = ScheduledTransfers;
